-- roblox/tools/install_arena_mode.lua  (GENERATED by roblox/tools/build_install_arena.py - do not edit;
-- change the repo files and re-run the generator)
-- Imports Dragon Arena into the arcade place in one step. Run it in Studio, in Edit mode: the command
-- bar, or the Studio MCP's execute_luau. It creates:
--   ServerStorage.Modes.Arena          (Folder)  Module + the server modules  [replaced if present]
--   ReplicatedStorage.Arena            (Folder)  ArenaConfig, Icons, Remotes, Theme, Client.*, Views.*,
--                                                 Events (the RemoteEvents) and Debug (BindableEvent)
--                                                 [replaced if present]
--   ReplicatedStorage.Core.Games.Arena (ModuleScript)  the GameRegistry entry  [replaced if present]
-- and, only with UPDATE_SHARED_STATESTORE = true, ServerStorage.Shared.StateStore (adds raw() / hello()).
-- It disables (never deletes) a standalone ArenaMain / ArenaHud left over from the old place, which
-- would open its own robot socket and set Lighting. It touches nothing else (not Lighting, not the
-- Workshop); the bay Workspace.Workshop.Bays.Bay4_Arena already names this mode ("Arena").

local UPDATE_SHARED_STATESTORE = false

local ServerStorage = game:GetService("ServerStorage")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local ServerScriptService = game:GetService("ServerScriptService")
local StarterPlayer = game:GetService("StarterPlayer")
local ChangeHistoryService = game:GetService("ChangeHistoryService")

local SERVICES = { ServerStorage = ServerStorage, ReplicatedStorage = ReplicatedStorage }
local made = {}

local function folderAt(path)
	local names = string.split(path, ".")
	local node = SERVICES[names[1]]
	assert(node, "unknown service in " .. path)
	for i = 2, #names do
		local child = node:FindFirstChild(names[i])
		if not child then
			child = Instance.new("Folder")
			child.Name = names[i]
			child.Parent = node
		end
		node = child
	end
	return node
end

local function put(path, className, source)
	local parentPath, name = string.match(path, "^(.*)%.([^%.]+)$")
	local parent = folderAt(parentPath)
	local old = parent:FindFirstChild(name)
	if old then
		old:Destroy()
	end
	local inst = Instance.new(className)
	inst.Name = name
	inst.Source = source
	inst.Parent = parent
	table.insert(made, path)
	return inst
end

local function replaceRoot(path)
	local parentPath, name = string.match(path, "^(.*)%.([^%.]+)$")
	local parent = folderAt(parentPath)
	local old = parent:FindFirstChild(name)
	if old then
		print("[install_arena_mode] replacing " .. old:GetFullName())
		old:Destroy()
	end
	local folder = Instance.new("Folder")
	folder.Name = name
	folder.Parent = parent
	return folder
end

pcall(function()
	ChangeHistoryService:SetWaypoint("Before installing Dragon Arena")
end)

assert(ReplicatedStorage:FindFirstChild("Core") and ReplicatedStorage.Core:FindFirstChild("GameRegistry"),
	"ReplicatedStorage.Core (the roles core) is missing: install the arcade lobby first")
if not (ServerStorage:FindFirstChild("Shared") and ServerStorage.Shared:FindFirstChild("StateStore")
	and ServerStorage.Shared:FindFirstChild("Bridge")) then
	warn("[install_arena_mode] ServerStorage.Shared.StateStore / Bridge are missing: the mode waits for them")
end

replaceRoot("ServerStorage.Modes.Arena")
replaceRoot("ReplicatedStorage.Arena")

local SOURCES = {}
table.insert(SOURCES, { path = "ServerStorage.Modes.Arena.Module", class = "ModuleScript", optional = false, source = [=[
-- ServerStorage.Modes.Arena.Module
-- Dragon Arena as an arcade mode (docs/arcade-plan.md "Mode contract"). The arcade requires this at
-- server start, calls Start(players) when the portal's join window closes, waits for Finished (up to
-- MaxDuration seconds) and then calls Stop(). It is Taher's standalone arena (roblox/arena/README.md)
-- with ArenaMain's wiring moved in here and everything it owned made per game:
--   Start(players)  builds the arena under one Model, workspace.DragonArena (ModelStreamingMode
--                   Persistent), centred on ArenaConfig.CENTER (0, 0, 400): clear of the lobby at the
--                   origin, Rising Flood at (400, 0, 0) and Pattern Match at (0, 0, -400). The floor
--                   comes from the robot's hello (the printed sheet), or the Letter sheet with no
--                   hello. Moves the players onto the spawn spots, makes Dragon Arena the active game
--                   (Core.GameRegistry: the robot's client shows Views.RobotView, the aerial camera),
--                   and runs one round (Rounds): intro, countdown, ROUND_SECONDS to survive, the result.
--   the game        players alive when the timer runs out win; a hit, a death or the lava eliminates.
--                   Then Finished:Fire({ { player = p, won = ... }, ... }) exactly once, one entry per
--                   player passed to Start (won = false for anyone eliminated or gone), also when
--                   everyone dies or leaves.
--   PlayerLeft(p)   the arcade's lobby pad (the part tagged "LobbyTeleporter" in the map, "Enabled"
--                   attribute true before and after the round, false during it) or the player left:
--                   won = false for them; the game ends right away if nobody is left.
--   Stop()          disconnects every connection, cancels every thread, clears the dragon's effects,
--                   puts every player's jump back, clears the active game (the views remove their
--                   client-side effects) and destroys the map. Start works again afterwards.
-- Robot data: no connection of its own. Link reads ServerStorage.Shared.StateStore and sends the
-- players' power-ups through ServerStorage.Shared.Bridge. Lighting: never touched (the arcade owns it);
-- the arena's look is made on each client by the views.
-- Roles: the robot operator is the dragon. They have no character, so the arcade never passes them to
-- Start; they watch Views.RobotView. Everything else on screen is Views.PlayerView, shown only to the
-- players in this game.
-- Testing hook, server only: ReplicatedStorage.Arena.Debug:Fire({ op = "endRound" }) runs the timer
-- out (survivors win); { op = "eliminate", name = "Player1" } eliminates that player.

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")

local ArenaShared = ReplicatedStorage:WaitForChild("Arena")
local Theme = require(ArenaShared:WaitForChild("Theme"))
local ArenaConfig = require(ArenaShared:WaitForChild("ArenaConfig"))
-- Required for its side effect: on the server, requiring Remotes creates the RemoteEvents, so they
-- exist from the moment the arcade loads this mode, before any view looks for them.
require(ArenaShared:WaitForChild("Remotes"))
local GameRegistry = require(ReplicatedStorage:WaitForChild("Core"):WaitForChild("GameRegistry"))
local Roles = require(ReplicatedStorage:WaitForChild("Core"):WaitForChild("Roles"))

local Tasks = require(script.Parent.Tasks)
local Link = require(script.Parent.Link)
local Mapping = require(script.Parent.Mapping)
local Arena = require(script.Parent.Arena)
local DragonArm = require(script.Parent.DragonArm)
local AttackDetect = require(script.Parent.AttackDetect)
local AttackFx = require(script.Parent.AttackFx)
local DragonEffects = require(script.Parent.DragonEffects)
local Pickups = require(script.Parent.Pickups)
local Rounds = require(script.Parent.Rounds)
local Sound = require(script.Parent.Sound)

local GAME_ID = "Arena" -- Core.Games.Arena
local MAP_NAME = "DragonArena"

local Mode = {}
Mode.DisplayName = "Dragon Arena"
Mode.Tip = "Dodge the robot dragon and survive the timer!"
Mode.WinsToUnlock = 0
Mode.Finished = Instance.new("BindableEvent")
-- Seconds from Start to Finished, at most (the arcade's timeout): the whole round plus a margin.
Mode.MaxDuration = ArenaConfig.INTRO_SECONDS + ArenaConfig.COUNTDOWN_SECONDS + ArenaConfig.ROUND_SECONDS
	+ ArenaConfig.RESULT_SECONDS + ArenaConfig.MAX_DURATION_MARGIN

local debugHook = ArenaShared:FindFirstChild("Debug")
if not debugHook then
	debugHook = Instance.new("BindableEvent")
	debugHook.Name = "Debug"
	debugHook.Parent = ArenaShared
end

local function log(fmt, ...)
	print("[Arena] " .. string.format(fmt, ...))
end

local session = nil -- the running game, nil between Stop and Start

-- Reports to the arcade, once per game. Deferred so a game that ends inside Start or inside the
-- arcade's own PlayerLeft call still reaches a listener the arcade connects right after.
local function finish(s, results)
	if s.finished then
		return
	end
	s.finished = true
	local names = {}
	for _, r in ipairs(results) do
		table.insert(names, r.player.Name .. "=" .. (r.won and "WIN" or "LOSE"))
	end
	log("finished: %s", #names > 0 and table.concat(names, " ") or "no players")
	task.defer(function()
		Mode.Finished:Fire(results)
	end)
end

-- One state frame through the dragon, its effects and attack detection. Dragon first: everything
-- after it reads where its parts ended up.
local function apply(s, frame)
	s.dragon:update(frame.arm, frame.arm_age)
	s.effects:update(frame.effects)
	s.rounds:setEffects(frame.effects)
	-- Always called, including on a stale frame. A stale arm is a harmless dragon (hard rule 5),
	-- and AttackDetect is what enforces that - it needs the frame to notice the staleness and shut
	-- down whatever was running.
	s.detect:update(frame)
end

-- Every Heartbeat: a new state frame if there is one, else, once the link has gone quiet for longer
-- than STALE_ARM_S, the last frame marked stale. (The standalone arena only heard frames, so a link
-- that died outright left a live dragon - and a burning fire cone - with nobody driving it.)
local function tick(s, dt)
	local state = Link.state()
	local now = os.clock()
	if type(state) == "table" then
		if state ~= s.lastState then
			s.lastState = state
			s.lastFrameAt = now
			s.staleSent = false
			apply(s, state)
		elseif not s.staleSent and now - s.lastFrameAt > ArenaConfig.STALE_ARM_S then
			s.staleSent = true
			local stale = table.clone(state)
			stale.arm_age = math.huge
			apply(s, stale)
		end
	end
	s.pickups:step(dt)
	s.rounds:step(dt)
end

-- The robot and the spectators have no character, so ServerScriptService.CoreRoles streams them
-- around the lobby (Player.ReplicationFocus = Workspace.RoleStreamFocus). The map itself is
-- Persistent, but the players on it are not: point those clients' streaming at the arena while it
-- runs, and put back whatever they had in Stop.
local function aimStreaming(s, player)
	local role = Roles.of(player)
	if (role == Roles.ROBOT or role == Roles.SPECTATOR) and s.foci[player] == nil and player.Parent then
		s.foci[player] = player.ReplicationFocus or false
		player.ReplicationFocus = s.focus
	end
end

local function restoreStreaming(s)
	for player, old in pairs(s.foci) do
		if player.Parent and player.ReplicationFocus == s.focus then
			player.ReplicationFocus = old or nil
		end
	end
	table.clear(s.foci)
end

-- Wires the attacks, hits and power-ups together (this was ArenaMain).
local function wire(s)
	local detect, fx, dragon, sound, rounds = s.detect, s.fx, s.dragon, s.sound, s.rounds

	detect.onSlam = function(tipMm, speed)
		fx:slam(tipMm, speed)
		sound:at("slam", Mapping.point(tipMm), 0.8)
	end
	detect.onSweepStart = function()
		fx:sweepStart()
		local head = dragon.segments[5]
		if head then
			sound:startLoop("sweep", head.core, 0.5)
		end
	end
	detect.onSweep = function(tipMm, dir)
		fx:sweep(tipMm, dir)
	end
	detect.onSweepEnd = function()
		fx:sweepEnd()
		sound:stopLoop("sweep")
	end
	detect.onFireStart = function(frac)
		fx:fireStart(frac)
		local head = dragon.segments[5]
		if head then
			sound:at("roar", head.core.Position, 0.9)
			sound:startLoop("flame", head.core, 0.6)
		end
	end
	detect.onFire = function(frac)
		fx:fire(frac)
	end
	detect.onFireEnd = function()
		fx:fireEnd()
		sound:stopLoop("flame")
	end

	-- A hit is the dragon's doing, so the round decides what it costs. AttackFx only reports it.
	fx.onHit = function(player, kind)
		local char = player.Character
		local root = char and char:FindFirstChild("HumanoidRootPart")
		if root then
			sound:at("eliminated", root.Position, 0.6)
		end
		rounds:eliminate(player, kind)
	end

	-- A player landed a debuff on the real arm. The toast says who and what, in the effect's own cool
	-- colour, never a warm one, because this is the players' win.
	s.pickups.onLanded = function(player, name)
		rounds:banner("DRAGON " .. Theme.effectLabel(name) .. "!", Theme.effectColor(name), 1.5, player.Name)
		sound:ui("debuff", 0.5)
	end

	rounds.onFinished = function(results)
		finish(s, results)
	end
end

-- players: the arcade's list of Players with characters.
function Mode.Start(players)
	if session then
		Mode.Stop()
	end
	local tasks = Tasks.new()
	local map = Instance.new("Model")
	map.Name = MAP_NAME
	map.ModelStreamingMode = Enum.ModelStreamingMode.Persistent
	map:SetAttribute("Center", ArenaConfig.CENTER)
	tasks:add(map)

	local s = { tasks = tasks, map = map, finished = false, lastState = nil, lastFrameAt = os.clock(), staleSent = false }
	session = s

	local hello = Link.hello()
	s.arena = Arena.new(map, tasks)
	s.arena:build(hello and hello.space) -- moves Mapping.ORIGIN: build before anything places parts

	local function inRound(player)
		return s.rounds ~= nil and s.rounds:isAlive(player)
	end
	s.dragon = DragonArm.new(map)
	s.detect = AttackDetect.new()
	s.fx = AttackFx.new(s.arena.fx, s.arena, s.dragon, tasks, inRound)
	s.effects = DragonEffects.new(s.dragon)
	s.pickups = Pickups.new(map, s.arena, Link, tasks, inRound)
	s.pickups:setEffects(hello and hello.effects)
	s.rounds = Rounds.new(s.arena, s.dragon, s.pickups, tasks)
	s.sound = Sound.new(s.arena.fx)
	wire(s)

	s.focus = Instance.new("Part")
	s.focus.Name = "StreamFocus"
	s.focus.Anchored, s.focus.CanCollide, s.focus.CanQuery, s.focus.CanTouch = true, false, false, false
	s.focus.Transparency = 1
	s.focus.Size = Vector3.one
	s.focus.Position = ArenaConfig.CENTER + Vector3.new(0, 20, 0)
	s.focus.Parent = map
	s.foci = {}

	map.Parent = workspace
	for _, player in ipairs(Players:GetPlayers()) do
		aimStreaming(s, player)
	end
	GameRegistry.setActive(GAME_ID)
	s.sound:ambience()

	tasks:connect(RunService.Heartbeat, function(dt)
		if session == s then
			tick(s, dt)
		end
	end)
	tasks:connect(Players.PlayerRemoving, function(player)
		s.foci[player] = nil
		s.rounds:playerLeft(player)
	end)
	tasks:connect(Players.PlayerAdded, function(player)
		-- CoreRoles gives a new client its role and its lobby focus first.
		tasks:delay(1, function()
			aimStreaming(s, player)
		end)
	end)
	tasks:connect(debugHook.Event, function(cmd)
		if type(cmd) ~= "table" then
			return
		end
		if cmd.op == "endRound" and s.rounds.state == "Round" then
			s.rounds.endsAt = 0 -- survivors win on the next tick
		elseif cmd.op == "eliminate" then
			local player = Players:FindFirstChild(tostring(cmd.name))
			if player and player:IsA("Player") then
				s.rounds:eliminate(player, "debug")
			end
		end
	end)

	local list = {}
	for _, p in ipairs(players or {}) do
		if typeof(p) == "Instance" and p:IsA("Player") then
			table.insert(list, p)
		end
	end
	log("started: %d player%s, link %s, floor from %s, centre %s, %d s round", #list, #list == 1 and "" or "s",
		Link.status(), hello and hello.space and "the robot's sheet" or "the default sheet",
		tostring(ArenaConfig.CENTER), ArenaConfig.ROUND_SECONDS)
	s.rounds:begin(list)
	return s
end

-- The arcade's lobby pad, or a player gone: they lose, and the game ends if nobody is left.
function Mode.PlayerLeft(player)
	local s = session
	if s and s.rounds then
		s.rounds:playerLeft(player)
	end
end

function Mode.Stop()
	local s = session
	if not s then
		return
	end
	session = nil
	-- Threads and connections first, so nothing runs against a half torn down arena.
	s.tasks.dead = true
	pcall(function()
		s.detect:stopAll()
	end)
	s.sound:stopAll()
	s.effects:clear()
	s.pickups:clear()
	s.rounds:cleanup() -- jump heights back, ArenaInGame / ArenaAlive cleared
	restoreStreaming(s)
	s.tasks:clean() -- also destroys the map
	if GameRegistry.active() == GAME_ID then
		GameRegistry.setActive(nil) -- every client's view exits and clears its effects
	end
	log("stopped")
end

return Mode
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Arena.Arena", class = "ModuleScript", optional = false, source = [=[
--!strict
-- The volcanic arena: floor, lava, cliffs, cover, background, impact marks, and the arcade's pieces
-- (the lobby pad, the spawn spots and the gallery the eliminated watch from).
--
-- IN THE ARCADE. Everything is built under the map Model the mode passes in (workspace.DragonArena),
-- around ArenaConfig.CENTER: build() moves Mapping.ORIGIN so the floor's centre lands there, with
-- its top surface at CENTER.Y. Nothing here touches Lighting any more - the arcade owns it. The look
-- the old applyLighting gave the scene (night, bloom, a warm grade) is made on each client by the
-- views instead (ReplicatedStorage.Arena.Client), while they are near the arena.
--
-- THE FLOOR IS THE PRINTED SHEET. The style guide (section 5) asks for the floor to be the outline
-- the real tip can reach, logged by driving the arm around with the jaw near the table. Nobody has
-- logged that yet, and until they do the sheet is the honest stand-in rather than a guess: it is
-- the actual work surface in front of the arm, its size arrives in `hello.space.sheet` instead of
-- being written down, and every block the game knows about sits on it.
--
-- The pedestal goes at `hello.space.arm_base_mm`, which is off the *top* edge of the sheet - the
-- arm really does stand behind the paper. So the guide's layout falls out of the real geometry for
-- free: the dragon is at the back against the cliff, and the floor fans out in front of it. No
-- round arena, so no safe spot behind the dragon where the shoulder pan cannot turn.
--
-- When the reach outline is finally logged, it replaces `floorFromSheet` and nothing else in the
-- mode changes. This is the only file that knows the floor's shape.
--
-- THE FLOOR IS ABOVE THE REAL TABLE. The arena floor sits at ARENA_FLOOR_MM above the paper, so
-- the dragon's head hits the in-game floor while the real jaw is still safely in the air. The
-- operator must never have to bang the arm into the table to land a slam.
--
--   local arena = Arena.new(map, tasks)
--   arena:build(hello and hello.space)   -- defaults to the Letter sheet with no hello

local CollectionService = game:GetService("CollectionService")
local Debris = game:GetService("Debris")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Theme = require(ReplicatedStorage.Arena.Theme)
local ArenaConfig = require(ReplicatedStorage.Arena.ArenaConfig)
local Mapping = require(script.Parent.Mapping)

local Arena = {}
Arena.__index = Arena

local C = Theme.Color

local function part(parent: Instance, name: string, color: Color3, material: Enum.Material,
	size: Vector3, cf: CFrame, collide: boolean?): BasePart
	local p = Instance.new("Part")
	p.Name = name
	p.Anchored = true
	p.CanCollide = collide ~= false
	p.CanQuery = collide ~= false
	p.CanTouch = false
	p.Material = material
	p.Color = color
	p.Size = size
	p.CFrame = cf
	p.TopSurface = Enum.SurfaceType.Smooth
	p.BottomSurface = Enum.SurfaceType.Smooth
	p.Parent = parent
	return p
end

-- parent: the map Model. tasks: the session's Tasks (threads for the crater cooling).
function Arena.new(parent: Instance, tasks: any)
	local self = setmetatable({}, Arena)
	self.tasks = tasks
	self.map = parent
	self.model = Instance.new("Model")
	self.model.Name = "Arena"
	self.model.Parent = parent
	-- Runtime effects (attacks, bursts, sounds) go here rather than loose in Workspace.
	self.fx = Instance.new("Folder")
	self.fx.Name = "Fx"
	self.fx.Parent = parent
	self.pad = nil :: BasePart?
	self.marks = {} :: { BasePart }      -- newest last; the oldest is removed past the budget
	self.lights = 0
	self.floorTopY = 0
	self.bounds = nil :: any
	self.built = false
	return self
end

-- Where the arena floor's *surface* is, in studs. Attack detection compares the real tip against
-- ARENA_FLOOR_MM in millimetres, but the visuals need the same plane in world units, and taking it
-- from Mapping is what keeps the two from drifting apart when the scale is retuned.
function Arena.floorY(self): number
	return Mapping.point({ x = 0, y = 0, z = ArenaConfig.ARENA_FLOOR_MM }).Y
end

-- The sheet rectangle, grown by the margin, with the back edge pushed out far enough to stand the
-- pedestal on. Returns millimetre bounds in the sheet frame.
function Arena.floorFromSheet(self, space: any): any
	local w = (space and space.sheet and space.sheet.w_mm) or 279.4
	local h = (space and space.sheet and space.sheet.h_mm) or 215.9
	local base = (space and space.arm_base_mm) or { w / 2, -44.5 }
	local m = ArenaConfig.ARENA_MARGIN_MM

	-- Capped at 1. Shrinking the floor is safe - a smaller floor is more reachable - but growing it
	-- past the sheet would hand players ground the arm cannot cover, which is the one thing the
	-- style guide says must never happen.
	local depthScale = math.clamp(ArenaConfig.ARENA_SCALE or 1, 0.15, 1)
	local widthScale = math.clamp(ArenaConfig.ARENA_WIDTH_SCALE or 1, 0.15, 1)

	-- The arm base is at a negative y (behind the top edge of the paper), so the floor has to reach
	-- back past it for the pedestal to stand on something. That back edge is the anchor: the floor
	-- shrinks *toward the dragon*, keeping it against the cliff while the far edge comes closer,
	-- rather than shrinking toward the middle and leaving the pedestal floating in the lava.
	local y0 = math.min(-m, base[2] - m)
	local y1 = y0 + ((h + m) - y0) * depthScale

	-- Across the sheet there is no anchor to respect, so this shrinks about the centre.
	local cx = w / 2
	local halfW = (w / 2 + m) * widthScale

	return {
		x0 = cx - halfW,
		x1 = cx + halfW,
		y0 = y0,
		y1 = y1,
		baseX = base[1],
		baseY = base[2],
		sheetW = w,
		sheetH = h,
	}
end

function Arena.build(self, space: any)
	if self.built then
		return
	end
	self.built = true
	local b = self:floorFromSheet(space)
	self.bounds = b
	-- Centre the floor on ArenaConfig.CENTER, its top surface at CENTER.Y. Everything below works
	-- through Mapping, so moving the origin moves the whole arena, the dragon and the hit tests.
	do
		local sc = Mapping.STUDS_PER_MM
		Mapping.ORIGIN = ArenaConfig.CENTER - Vector3.new((b.x0 + b.x1) / 2 * sc,
			ArenaConfig.ARENA_FLOOR_MM * sc, (b.y0 + b.y1) / 2 * sc)
	end
	-- Platform heights are in units of the player's jump, which is in turn scaled to the real cube
	-- size from `hello`. Hardcoding either one puts a ledge out of reach the moment the scale or
	-- the block size changes.
	self.cubeMm = (space and space.cube_mm) or 48
	local s = Mapping.STUDS_PER_MM
	local floorY = self:floorY()
	self.floorTopY = floorY

	local function world(xMm: number, yMm: number, yStuds: number): Vector3
		return Mapping.ORIGIN + Vector3.new(xMm * s, yStuds, yMm * s)
	end

	local wx = (b.x1 - b.x0) * s
	local wz = (b.y1 - b.y0) * s
	local cx = (b.x0 + b.x1) / 2
	local cz = (b.y0 + b.y1) / 2

	-- Floor. Dark obsidian, mostly flat. Orange stays off it except at the lava edge and on
	-- temporary impact glow, so fire and shockwaves have something dark to stand out against.
	local floor = part(self.model, "Floor", C.Obsidian, Enum.Material.Basalt,
		Vector3.new(wx, 4, wz), CFrame.new(world(cx, cz, floorY - 2)))
	self.floor = floor

	-- A few thin cracks, Neon at high transparency. Few on purpose: a floor lit all over competes
	-- with the fire.
	for k = 1, 6 do
		local fx = b.x0 + (b.x1 - b.x0) * (k / 7)
		local crack = part(self.model, "Crack" .. k, C.Ember, Enum.Material.Neon,
			Vector3.new(0.6, 0.2, wz * (0.3 + 0.4 * ((k * 7) % 5) / 5)),
			CFrame.new(world(fx, cz, floorY + 0.02)) * CFrame.Angles(0, math.rad((k % 3) * 12 - 12), 0),
			false)
		crack.Transparency = 0.4
	end

	self:buildLava(b, s, floorY)
	self:buildCliffs(b, s, floorY)
	self:buildCover(b, s, floorY)
	self:buildBackground(b, s, floorY)
	self:buildEmbers()
	self:buildPad(b, s, floorY)
	self:buildGallery(b, s, floorY)
end

-- Lava surrounds the reachable floor: everything the dragon cannot hit must be fatal, or players
-- find a corner to stand in and the round stops being a dodge.
function Arena.buildLava(self, b: any, s: number, floorY: number)
	local lw = ArenaConfig.LAVA_WIDTH_MM
	local sides = {
		{ x0 = b.x0 - lw, x1 = b.x1 + lw, y0 = b.y0 - lw, y1 = b.y0 },
		{ x0 = b.x0 - lw, x1 = b.x1 + lw, y0 = b.y1,      y1 = b.y1 + lw },
		{ x0 = b.x0 - lw, x1 = b.x0,      y0 = b.y0,      y1 = b.y1 },
		{ x0 = b.x1,      x1 = b.x1 + lw, y0 = b.y0,      y1 = b.y1 },
	}
	for i, q in sides do
		local size = Vector3.new((q.x1 - q.x0) * s, 3, (q.y1 - q.y0) * s)
		local at = Mapping.ORIGIN + Vector3.new((q.x0 + q.x1) / 2 * s, floorY - 2.4, (q.y0 + q.y1) / 2 * s)
		part(self.model, "Lava" .. i, C.Lava, Enum.Material.CrackedLava, size, CFrame.new(at))
		-- A Neon strip along the inner edge does the glow. Neon plus Bloom is far cheaper than a
		-- light, which matters because Future lighting makes lights expensive.
		local glow = part(self.model, "LavaGlow" .. i, C.LavaHot, Enum.Material.Neon,
			Vector3.new(size.X, 0.4, size.Z),
			CFrame.new(at + Vector3.new(0, 1.6, 0)), false)
		glow.Transparency = 0.3
	end

	-- At most MAX_ENV_POINT_LIGHTS in the lava. Everything else glows with Neon and Bloom.
	local n = math.min(ArenaConfig.MAX_ENV_POINT_LIGHTS, 8)
	for k = 1, n do
		local a = (k / n) * math.pi * 2
		local host = part(self.model, "LavaLight" .. k, C.Lava, Enum.Material.Neon,
			Vector3.new(1, 1, 1),
			CFrame.new(Mapping.ORIGIN + Vector3.new(
				((b.x0 + b.x1) / 2 + math.cos(a) * (b.x1 - b.x0) * 0.62) * s,
				floorY + 1,
				((b.y0 + b.y1) / 2 + math.sin(a) * (b.y1 - b.y0) * 0.62) * s)), false)
		host.Transparency = 1
		local l = Instance.new("PointLight")
		l.Color = C.Lava
		l.Range = 20
		l.Brightness = 2
		l.Parent = host
		self.lights += 1
	end
end

-- The back wall the pedestal stands against: the dragon's lair. Side walls keep the camera from
-- looking out into nothing.
function Arena.buildCliffs(self, b: any, s: number, floorY: number)
	local h = ArenaConfig.CLIFF_HEIGHT
	local lw = ArenaConfig.LAVA_WIDTH_MM
	local back = part(self.model, "BackCliff", C.Basalt, Enum.Material.Rock,
		Vector3.new((b.x1 - b.x0 + lw * 2) * s, h, 10),
		CFrame.new(Mapping.ORIGIN + Vector3.new((b.x0 + b.x1) / 2 * s, floorY + h / 2, (b.y0 - 5) * s)))
	part(self.model, "BackCliffEdge", C.BasaltEdge, Enum.Material.Slate,
		Vector3.new(back.Size.X, 1.2, 11),
		CFrame.new(back.Position + Vector3.new(0, h / 2, 0)), false)
end

-- Cover and height. Rocks block fire (the cone raycasts), and the low platforms give somewhere to
-- jump. Everything is inside the floor, so there is nowhere the dragon cannot reach.
function Arena.buildCover(self, b: any, s: number, floorY: number)
	local jump = Mapping.jumpHeight(self.cubeMm or 48)
	local spots = {
		{ fx = 0.22, fy = 0.34, r = 9,  plat = false },
		{ fx = 0.76, fy = 0.30, r = 11, plat = false },
		{ fx = 0.50, fy = 0.66, r = 8,  plat = false },
		{ fx = 0.14, fy = 0.72, r = 7,  plat = true,  lift = 0.55 },
		{ fx = 0.86, fy = 0.70, r = 7,  plat = true,  lift = 0.55 },
		{ fx = 0.34, fy = 0.52, r = 6,  plat = true,  lift = 1.15 },
		{ fx = 0.66, fy = 0.50, r = 6,  plat = true,  lift = 1.15 },
	}
	for i, sp in spots do
		local xMm = b.x0 + (b.x1 - b.x0) * sp.fx
		local yMm = b.y0 + (b.y1 - b.y0) * sp.fy
		-- Platform heights are given in units of the arena's JumpHeight, so retuning the scale
		-- retunes the climb instead of silently putting a ledge out of reach.
		local y = floorY + (sp.plat and jump * (sp.lift or 0.55) or sp.r * 0.4)
		local at = Mapping.ORIGIN + Vector3.new(xMm * s, y, yMm * s)
		if sp.plat then
			part(self.model, "Platform" .. i, C.Basalt, Enum.Material.Slate,
				Vector3.new(sp.r * 2.6, 2.2, sp.r * 2.6), CFrame.new(at))
			part(self.model, "PlatformEdge" .. i, C.BasaltEdge, Enum.Material.Slate,
				Vector3.new(sp.r * 2.7, 0.5, sp.r * 2.7),
				CFrame.new(at + Vector3.new(0, 1.3, 0)), false)
		else
			local rock = part(self.model, "Rock" .. i, C.Basalt, Enum.Material.Rock,
				Vector3.new(sp.r * 1.7, sp.r * 1.5, sp.r * 1.9),
				CFrame.new(at) * CFrame.Angles(0, i * 0.7, 0.06))
			part(self.model, "RockEdge" .. i, C.BasaltEdge, Enum.Material.Slate,
				Vector3.new(sp.r * 1.4, 0.5, sp.r * 1.6),
				rock.CFrame * CFrame.new(0, sp.r * 0.75, 0), false)
		end
	end
end

-- Tall spires and lavafalls outside the play area, dark against the sky. They frame the dragon,
-- and must never be brighter than it: a background that out-glows the dragon flattens the scene.
function Arena.buildBackground(self, b: any, s: number, floorY: number)
	local lw = ArenaConfig.LAVA_WIDTH_MM
	for k = 1, 10 do
		local a = (k / 10) * math.pi * 2 + 0.3
		local dist = (b.x1 - b.x0) * 0.7 + lw
		local xMm = (b.x0 + b.x1) / 2 + math.cos(a) * dist
		local yMm = (b.y0 + b.y1) / 2 + math.sin(a) * dist * 0.8
		local h = 70 + (k % 4) * 45
		local spire = part(self.model, "Spire" .. k, C.Basalt, Enum.Material.Rock,
			Vector3.new(14 + (k % 3) * 6, h, 14 + (k % 2) * 7),
			CFrame.new(Mapping.ORIGIN + Vector3.new(xMm * s, floorY + h / 2 - 6, yMm * s))
				* CFrame.Angles(0, a, 0),
			false)
		if k % 3 == 0 then
			local fall = part(self.model, "Lavafall" .. k, C.Lava, Enum.Material.Neon,
				Vector3.new(3, h * 0.7, 1.5),
				spire.CFrame * CFrame.new(spire.Size.X / 2 + 0.6, -h * 0.1, 0), false)
			fall.Transparency = 0.25
		end
	end
end

-- Ambient embers drifting up over the arena. One emitter, low rate: this is atmosphere, and it has
-- to leave room in the ~400-particle budget for the fire and the slams.
function Arena.buildEmbers(self)
	if not self.bounds then
		return
	end
	local b = self.bounds
	local s = Mapping.STUDS_PER_MM
	local host = part(self.model, "EmberSource", C.Ember, Enum.Material.Neon, Vector3.new(1, 1, 1),
		CFrame.new(Mapping.ORIGIN + Vector3.new((b.x0 + b.x1) / 2 * s, self.floorTopY + 30,
			(b.y0 + b.y1) / 2 * s)), false)
	host.Transparency = 1

	local e = Instance.new("ParticleEmitter")
	e.Name = "Embers"
	e.Color = ColorSequence.new(C.Ember, C.LavaHot)
	e.Size = NumberSequence.new(0.4)
	e.Lifetime = NumberRange.new(4, 7)
	e.Rate = 6
	e.Speed = NumberRange.new(2, 5)
	e.SpreadAngle = Vector2.new(25, 25)
	e.LightEmission = 1
	e.Transparency = NumberSequence.new({
		NumberSequenceKeypoint.new(0, 1),
		NumberSequenceKeypoint.new(0.2, 0.2),
		NumberSequenceKeypoint.new(1, 1),
	})
	e.EmissionDirection = Enum.NormalId.Top
	e.Shape = Enum.ParticleEmitterShape.Box
	e.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume
	-- Sized before the emitter is parented: the Box shape emits from the host's volume, so a host
	-- still 1x1x1 at that moment drips embers from a single point above the middle of the arena.
	host.Size = Vector3.new((b.x1 - b.x0) * s, 2, (b.y1 - b.y0) * s)
	e.Parent = host
end

-- ---------------------------------------------------------------------------------------------
-- Impact marks. Craters and scorch patches are left *after* a hit, which hard rule 1 allows -
-- they are history, not a prediction of where the next strike lands.
-- ---------------------------------------------------------------------------------------------

function Arena.trimMarks(self)
	while #self.marks > ArenaConfig.MAX_IMPACT_MARKS do
		local oldest = table.remove(self.marks, 1)
		if oldest then
			oldest:Destroy()
		end
	end
end

-- A crater: an ObsidianDeep centre with an Ember rim that cools to Scorch over a few seconds, then
-- is cleaned up. Without the cleanup the floor fills with rims and the newest slam stops reading.
function Arena.addCrater(self, at: Vector3, radius: number)
	local y = self.floorTopY + 0.05
	local centre = part(self.model, "Crater", C.ObsidianDeep, Enum.Material.Basalt,
		Vector3.new(radius * 1.6, 0.3, radius * 1.6),
		CFrame.new(at.X, y, at.Z), false)
	centre.Shape = Enum.PartType.Cylinder
	centre.CFrame = CFrame.new(at.X, y, at.Z) * CFrame.Angles(0, 0, math.pi / 2)

	local rim = part(self.model, "CraterRim", C.Ember, Enum.Material.Neon,
		Vector3.new(radius * 1.9, 0.22, radius * 1.9),
		CFrame.new(at.X, y + 0.02, at.Z), false)
	rim.Shape = Enum.PartType.Cylinder
	rim.CFrame = CFrame.new(at.X, y + 0.02, at.Z) * CFrame.Angles(0, 0, math.pi / 2)
	rim.Transparency = 0.1
	rim.Parent = centre

	table.insert(self.marks, centre)
	self:trimMarks()

	-- The rim cools from Ember to Scorch. This is the mark changing after the fact, not the dragon
	-- being animated, so hard rule 2 is untouched.
	self.tasks:spawn(function()
		local t0 = os.clock()
		local cool = ArenaConfig.IMPACT_MARK_COOL_S
		while rim.Parent and os.clock() - t0 < cool do
			local f = (os.clock() - t0) / cool
			rim.Color = C.Ember:Lerp(C.Scorch, f)
			rim.Transparency = 0.1 + 0.6 * f
			task.wait(0.05)
		end
		if rim.Parent then
			rim.Material = Enum.Material.Basalt
			rim.Color = C.Scorch
			rim.Transparency = 0.3
		end
	end)
	Debris:AddItem(centre, ArenaConfig.IMPACT_MARK_LIFETIME_S)
end

function Arena.addScorch(self, at: Vector3, radius: number)
	local patch = part(self.model, "Scorch", C.Scorch, Enum.Material.Basalt,
		Vector3.new(radius * 1.5, 0.25, radius * 1.5),
		CFrame.new(at.X, self.floorTopY + 0.04, at.Z), false)
	patch.Shape = Enum.PartType.Cylinder
	patch.CFrame = CFrame.new(at.X, self.floorTopY + 0.04, at.Z) * CFrame.Angles(0, 0, math.pi / 2)
	patch.Transparency = 0.25
	table.insert(self.marks, patch)
	self:trimMarks()
	Debris:AddItem(patch, ArenaConfig.IMPACT_MARK_LIFETIME_S)
end

-- Is this world point on the playable floor? Pickups and spawns ask, so nothing lands in the lava
-- or somewhere the dragon cannot reach.
function Arena.inBounds(self, at: Vector3): boolean
	if not self.bounds then
		return false
	end
	local b = self.bounds
	local s = Mapping.STUDS_PER_MM
	local local_ = at - Mapping.ORIGIN
	local xMm = local_.X / s
	local yMm = local_.Z / s
	return xMm > b.x0 and xMm < b.x1 and yMm > b.y0 and yMm < b.y1
end

-- A random point on the floor, inside reach, for a pickup or a spawn. Keeps clear of the pedestal
-- end, where the tip cannot get down to the floor.
function Arena.randomFloorPoint(self, rng: Random): Vector3
	local b = self.bounds
	local s = Mapping.STUDS_PER_MM
	local xMm = b.x0 + (b.x1 - b.x0) * rng:NextNumber(0.08, 0.92)
	-- The dead zone close to the base: the tip cannot reach the floor there, so nothing spawns in
	-- it. Players must never find a spot the dragon cannot hit.
	local yMm = b.y0 + (b.y1 - b.y0) * rng:NextNumber(0.3, 0.94)
	return Mapping.ORIGIN + Vector3.new(xMm * s, self.floorTopY + 3, yMm * s)
end

-- ---------------------------------------------------------------------------------------------
-- The arcade's pieces
-- ---------------------------------------------------------------------------------------------

-- The lobby pad: the arcade's way back (a part tagged "LobbyTeleporter" with an "Enabled"
-- attribute; the arcade moves whoever steps on it while Enabled and calls Mode.PlayerLeft). It sits
-- at the front of the floor, the far end from the dragon, among the spawn spots.
function Arena.buildPad(self, b: any, s: number, floorY: number)
	local at = Mapping.ORIGIN + Vector3.new((b.x0 + b.x1) / 2 * s, floorY + 0.15,
		(b.y0 + (b.y1 - b.y0) * ArenaConfig.PAD_FRAC) * s)
	local pad = part(self.map, "LobbyTeleporter", C.Power, Enum.Material.Neon,
		Vector3.new(0.3, ArenaConfig.PAD_SIZE, ArenaConfig.PAD_SIZE),
		CFrame.new(at) * CFrame.Angles(0, 0, math.pi / 2), false)
	pad.Shape = Enum.PartType.Cylinder
	pad.CanTouch = true
	pad.CanQuery = true
	pad.Transparency = 0.35
	pad:SetAttribute("Enabled", false)
	CollectionService:AddTag(pad, "LobbyTeleporter")

	local gui = Instance.new("BillboardGui")
	gui.Name = "Label"
	gui.Size = UDim2.fromOffset(180, 36)
	gui.StudsOffsetWorldSpace = Vector3.new(0, 6, 0)
	gui.MaxDistance = 140
	gui.Parent = pad
	local label = Instance.new("TextLabel")
	label.Size = UDim2.fromScale(1, 1)
	label.BackgroundTransparency = 1
	label.FontFace = Theme.Font.Display
	label.TextScaled = true
	label.TextColor3 = C.UiText
	label.TextStrokeTransparency = 0.3
	label.Text = "BACK TO LOBBY"
	label.Parent = gui
	self.pad = pad
	self.padLabel = label
end

-- On before and after the round, off during it.
function Arena.setPad(self, on: boolean)
	local pad = self.pad
	if not pad then
		return
	end
	pad:SetAttribute("Enabled", on)
	pad.Transparency = if on then 0.35 else 0.85
	if self.padLabel then
		self.padLabel.Visible = on
	end
end

-- n spawn spots in rows across the front of the floor, ArenaConfig.SPAWN_SPACING apart (sized for
-- the arcade's 1.5x characters), either side of the pad and clear of it. Floor surface points.
function Arena.spawnPoints(self, n: number): { Vector3 }
	local b = self.bounds
	local s = Mapping.STUDS_PER_MM
	local spacing = ArenaConfig.SPAWN_SPACING
	local perRow = math.max(2, math.floor((b.x1 - b.x0) * s * 0.84 / spacing))
	local cx = (b.x0 + b.x1) / 2 * s
	local frontZ = (b.y0 + (b.y1 - b.y0) * ArenaConfig.SPAWN_FRAC) * s
	local padAt = self.pad and self.pad.Position
	local out = {}
	local k = 0
	while #out < math.max(n, 1) and k < 400 do
		local row = k // perRow
		local col = k % perRow
		k += 1
		-- Columns fill outward from the middle: 0, -1, +1, -2, +2 ... so a small group stands together.
		local side = if col % 2 == 0 then col // 2 else -(col // 2 + 1)
		local at = Mapping.ORIGIN + Vector3.new(cx + (side + 0.5) * spacing, 0, frontZ - row * spacing)
		at = Vector3.new(at.X, self.floorTopY, at.Z)
		local clear = padAt == nil
			or (Vector3.new(at.X - padAt.X, 0, at.Z - padAt.Z)).Magnitude > ArenaConfig.PAD_SIZE / 2 + spacing / 2
		if clear and self:inBounds(at) then
			table.insert(out, at)
		end
	end
	while #out < n do
		table.insert(out, out[(#out % math.max(#out, 1)) + 1] or self:floorCentre())
	end
	return out
end

-- Where the dragon stands (the pedestal), for facing players toward it.
function Arena.dragonEnd(self): Vector3
	local b = self.bounds
	local s = Mapping.STUDS_PER_MM
	return Mapping.ORIGIN + Vector3.new(b.baseX * s, self.floorTopY, b.baseY * s)
end

function Arena.floorCentre(self): Vector3
	local b = self.bounds
	local s = Mapping.STUDS_PER_MM
	return Mapping.ORIGIN + Vector3.new((b.x0 + b.x1) / 2 * s, self.floorTopY, (b.y0 + b.y1) / 2 * s)
end

-- The gallery: a walled ledge past the far lava, GALLERY_HEIGHT above the floor, facing the dragon.
-- The eliminated respawn here (Rounds.toGallery). It is out of reach both ways: the dragon cannot
-- get to it, and a spectator cannot drop onto the floor and get back in the way.
function Arena.buildGallery(self, b: any, s: number, floorY: number)
	local lw = ArenaConfig.LAVA_WIDTH_MM
	local w = ArenaConfig.GALLERY_SIZE.X
	local d = ArenaConfig.GALLERY_SIZE.Y
	local y = floorY + ArenaConfig.GALLERY_HEIGHT
	local at = Mapping.ORIGIN + Vector3.new((b.x0 + b.x1) / 2 * s, y - 1, (b.y1 + lw) * s + d / 2)
	local g = Instance.new("Model")
	g.Name = "Gallery"
	g.Parent = self.model
	part(g, "Deck", C.Basalt, Enum.Material.Slate, Vector3.new(w, 2, d), CFrame.new(at))
	local wallH = 10
	local walls = {
		{ Vector3.new(w, wallH, 1), Vector3.new(0, wallH / 2 + 1, -d / 2) }, -- the arena side
		{ Vector3.new(w, wallH, 1), Vector3.new(0, wallH / 2 + 1, d / 2) },
		{ Vector3.new(1, wallH, d), Vector3.new(-w / 2, wallH / 2 + 1, 0) },
		{ Vector3.new(1, wallH, d), Vector3.new(w / 2, wallH / 2 + 1, 0) },
	}
	for i, spec in walls do
		local wall = part(g, "Wall" .. i, C.BasaltEdge, Enum.Material.Glass, spec[1], CFrame.new(at + spec[2]))
		wall.Transparency = if i == 1 then 0.8 else 0.3
	end
	-- Columns down into the lava, so it stands on something.
	for i, dx in { -w / 2 + 3, w / 2 - 3 } do
		part(g, "Column" .. i, C.Basalt, Enum.Material.Rock, Vector3.new(4, ArenaConfig.GALLERY_HEIGHT + 4, 4),
			CFrame.new(at + Vector3.new(dx, -ArenaConfig.GALLERY_HEIGHT / 2 - 1, 0)), false)
	end
	self.gallery = { centre = at + Vector3.new(0, 1, 0), w = w, d = d }
end

-- A standing spot on the gallery deck: column col of perRow, row row (rows go back from the rail).
function Arena.galleryPoint(self, col: number, row: number, perRow: number): Vector3
	local g = self.gallery
	local spacing = math.min(ArenaConfig.SPAWN_SPACING, (g.w - 4) / perRow)
	local x = (col - (perRow - 1) / 2) * spacing
	local z = -g.d / 2 + 4 + (row % 3) * 5
	return g.centre + Vector3.new(x, 0, z)
end

-- Off the playable floor and down at its surface: in the lava. The rocks and platforms are all
-- inside the floor's bounds, so standing on them never counts.
function Arena.offFloor(self, at: Vector3): boolean
	if not self.bounds then
		return false
	end
	return not self:inBounds(at) and at.Y < self.floorTopY + 12
end

return Arena
]=] })
table.insert(SOURCES, { path = "ServerStorage.Modes.Arena.AttackDetect", class = "ModuleScript", optional = false, source = [=[
--!strict
-- Works out what the dragon is doing from the arm's own motion, as it happens.
--
-- There is no "attack" message on the wire and there cannot be one: the operator is a person
-- holding a leader arm, and nothing upstream knows they are about to slam. So the server watches
-- successive state frames and decides. This is also why hard rule 1 forbids predictive telegraphs -
-- the game finds out at the same instant the players do.
--
-- TIMING COMES FROM `ts`, NOT FROM HEARTBEAT. Bridge keeps only the newest frame and drops the
-- rest, so the gap between the frames actually seen is not Heartbeat's delta time. Dividing a real
-- position change by the wrong dt invents speed, and invented speed fires slams that never
-- happened. Every velocity here is differentiated from the frame's own `ts`.
--
-- EVERY THRESHOLD IS A GUESS. The numbers in ArenaConfig are starting values from the style guide,
-- not measurements. Log real tip speed in teleop and set them from that - and remember the follower
-- caps its own per-tick movement (`max_relative_target = 10` in robot/arm.py), so its top speed is
-- bounded and a threshold above that can never fire at all.
--
--   local detect = AttackDetect.new()
--   detect.onSlam = function(tipMm, speed) ... end
--   every new state frame: detect:update(s)   (Module, from Link.state())

local ReplicatedStorage = game:GetService("ReplicatedStorage")

local ArenaConfig = require(ReplicatedStorage.Arena.ArenaConfig)

local AttackDetect = {}
AttackDetect.__index = AttackDetect

function AttackDetect.new()
	local self = setmetatable({}, AttackDetect)
	self.history = {} :: { { x: number, y: number, z: number, ts: number } }
	self.vel = { x = 0, y = 0, z = 0 }
	self.armed = true            -- a slam needs the tip to have lifted since the last one
	self.sweeping = false
	self.firing = false
	self.dormant = false
	self.lastTs = nil :: number?

	-- The jaw's observed range, learned exactly as DragonArm does and for the same reason: what
	-- reading means "open" differs from gripper to gripper.
	self.gripLo = nil :: number?
	self.gripHi = nil :: number?

	-- Hooks. Set whichever matter; an unset one is simply not called.
	self.onSlam = nil :: ((tipMm: any, speed: number) -> ())?
	self.onSweepStart = nil :: ((dir: any) -> ())?
	self.onSweep = nil :: ((tipMm: any, dir: any) -> ())?
	self.onSweepEnd = nil :: (() -> ())?
	self.onFireStart = nil :: ((frac: number) -> ())?
	self.onFire = nil :: ((frac: number) -> ())?
	self.onFireEnd = nil :: (() -> ())?
	return self
end

local function call(fn: any, ...)
	if fn then
		local ok, err = pcall(fn, ...)
		if not ok then
			warn("[AttackDetect] handler errored: " .. tostring(err))
		end
	end
end

-- Velocity in mm/s, smoothed across the last few frames so one jittery FK sample cannot read as a
-- slam. A gap longer than VELOCITY_MAX_GAP_S means the link stalled rather than the arm moving
-- fast, so the estimate restarts instead of dividing a large move by a large dt.
function AttackDetect.updateVelocity(self, tip: any, ts: number)
	local h = self.history
	local last = h[#h]
	if last and ts - last.ts > ArenaConfig.VELOCITY_MAX_GAP_S then
		table.clear(h)
		self.vel = { x = 0, y = 0, z = 0 }
	end
	if last and ts <= last.ts then
		return                   -- a repeated or out-of-order frame carries no new motion
	end

	table.insert(h, { x = tip.x, y = tip.y, z = tip.z, ts = ts })
	while #h > ArenaConfig.VELOCITY_SMOOTH_FRAMES + 1 do
		table.remove(h, 1)
	end
	if #h < 2 then
		return
	end
	local a, b = h[1], h[#h]
	local dt = b.ts - a.ts
	if dt <= 0 then
		return
	end
	self.vel = { x = (b.x - a.x) / dt, y = (b.y - a.y) / dt, z = (b.z - a.z) / dt }
end

-- Jaw opening 0..1 on this gripper's own learned range. Same method as bridge/world.py
-- `_grip_state` and DragonArm:jawFraction.
function AttackDetect.jawFraction(self, grip: number?): number
	if grip == nil then
		return 0
	end
	self.gripLo = self.gripLo and math.min(self.gripLo, grip) or grip
	self.gripHi = self.gripHi and math.max(self.gripHi, grip) or grip
	local span = (self.gripHi :: number) - (self.gripLo :: number)
	if span >= ArenaConfig.GRIP_SPAN_MIN then
		return math.clamp((grip - (self.gripLo :: number)) / span, 0, 1)
	end
	return math.clamp(grip / ArenaConfig.GRIP_OPEN_PCT, 0, 1)
end

function AttackDetect.stopAll(self)
	if self.sweeping then
		self.sweeping = false
		call(self.onSweepEnd)
	end
	if self.firing then
		self.firing = false
		call(self.onFireEnd)
	end
end

function AttackDetect.update(self, state: any)
	local arm = state and state.arm
	if arm == nil or arm.tip == nil then
		return
	end

	-- A stale arm is a harmless dragon (hard rule 5). Stop whatever was running: a fire cone left
	-- burning on a dead link would keep killing players with nobody driving it.
	if (state.arm_age or 0) > ArenaConfig.STALE_ARM_S then
		if not self.dormant then
			self.dormant = true
			self:stopAll()
			table.clear(self.history)
		end
		return
	end
	self.dormant = false

	local ts = state.ts or os.clock()
	self:updateVelocity(arm.tip, ts)

	local floor = ArenaConfig.ARENA_FLOOR_MM
	local height = arm.tip.z - floor          -- how far the real tip is above the arena floor
	local v = self.vel

	self:detectSlam(arm.tip, height, v)
	self:detectSweep(arm.tip, height, v)
	self:detectFire(arm.joints and arm.joints.gripper)
end

-- The tip comes within SLAM_HEIGHT_MM of the arena floor while moving down fast. One slam per
-- descent: without the re-arm, a tip resting near the floor with a little jitter re-triggers every
-- frame and the arena fills with shockwaves.
--
-- `z` is up off the paper, so descending is a negative z velocity.
function AttackDetect.detectSlam(self, tip: any, height: number, v: any)
	if height > ArenaConfig.SLAM_REARM_MM then
		self.armed = true
		return
	end
	if not self.armed then
		return
	end
	if height <= ArenaConfig.SLAM_HEIGHT_MM and -v.z >= ArenaConfig.SLAM_SPEED_MMS then
		self.armed = false
		call(self.onSlam, tip, -v.z)
	end
end

-- The tip is low and moving sideways fast. Sideways is the x/y plane of the sheet; the vertical
-- component is deliberately excluded, or a fast slam would also register as a sweep.
function AttackDetect.detectSweep(self, tip: any, height: number, v: any)
	local lateral = math.sqrt(v.x * v.x + v.y * v.y)
	local low = height <= ArenaConfig.SWEEP_HEIGHT_MM
	local fast = lateral >= ArenaConfig.SWEEP_SPEED_MMS
	local dir = { x = v.x, y = v.y, speed = lateral }

	if low and fast then
		if not self.sweeping then
			self.sweeping = true
			call(self.onSweepStart, dir)
		end
		call(self.onSweep, tip, dir)
	elseif self.sweeping then
		self.sweeping = false
		call(self.onSweepEnd)
	end
end

-- Fire needs BOTH tests, and the second one is the whole point.
--
-- `butterfingers` holds the jaw at least 18% open for its whole duration (BUTTERFINGERS_OPEN_PCT
-- in bridge/effects.py). On the learned range alone a jaw jammed that far open can read as a roar,
-- so a player spending a power-up to jam the dragon's jaw would instead hand it 8 seconds of free
-- fire. The absolute floor, set safely above 18, is what stops that - and it has to be an absolute
-- reading, because the learned range is exactly what the debuff distorts.
function AttackDetect.detectFire(self, grip: number?)
	local frac = self:jawFraction(grip)
	local openEnough = frac >= ArenaConfig.FIRE_OPEN_FRAC
	local aboveJamFloor = (grip or 0) >= ArenaConfig.FIRE_MIN_PCT

	if openEnough and aboveJamFloor then
		if not self.firing then
			self.firing = true
			call(self.onFireStart, frac)
		end
		call(self.onFire, frac)
	elseif self.firing then
		-- Stops on the same frame the jaw drops below the threshold: a fire cone that lingers is a
		-- hit volume the player cannot see.
		self.firing = false
		call(self.onFireEnd)
	end
end

return AttackDetect
